#!/usr/bin/env python3
"""Prepare two files to paste into Wokwi, keeping the shared sources canonical."""
from pathlib import Path
import argparse
from dataclasses import asdict
import json
import shutil
import sys

ROOT = Path(__file__).resolve().parents[1]
FIRMWARE = ROOT / "firmware/stockweight"
OUTPUT = ROOT / "build/wokwi"
sys.path.insert(0, str(ROOT))
from app.mqtt_config import DEFAULT_CONFIG, MqttConfig, load_config


def prepare(config: MqttConfig | None = None) -> Path:
    OUTPUT.mkdir(parents=True, exist_ok=True)
    sections = [
        "// Generated by scripts/prepare_wokwi.py. Edit firmware/stockweight/ instead.\n",
        "#include <Arduino.h>\n#include <esp_random.h>\n",
    ]
    names = ["stock_engine.h", "mass_source.h"]
    if config:
        sections.append("\n".join([
            "#define STOCKWEIGHT_MQTT 1",
            "#define SW_MQTT_HOST " + json.dumps(config.host),
            "#define SW_MQTT_PORT " + str(config.port),
            "#define SW_MQTT_PREFIX " + json.dumps(config.prefix),
            "#define SW_DEVICE_ID " + json.dumps(config.device_id),
        ]))
        names.append("mqtt_transport.h")
    names.append("stockweight.ino")
    for name in names:
        source = (FIRMWARE / name).read_text(encoding="utf-8")
        lines = [line for line in source.splitlines() if line.strip() not in {
            "#pragma once", '#include "mass_source.h"', '#include "stock_engine.h"',
            "#include <Arduino.h>", "#include <esp_random.h>",
            '#include "mqtt_transport.h"',
        }]
        sections.append(f"\n// ---- {name} ----\n" + "\n".join(lines) + "\n")
    (OUTPUT / "sketch.ino").write_text("\n".join(sections), encoding="utf-8")
    shutil.copyfile(FIRMWARE / "diagram.json", OUTPUT / "diagram.json")
    (OUTPUT / "libraries.txt").write_text("PubSubClient@2.8\n" if config else "", encoding="utf-8")
    return OUTPUT


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Preparar arquivos para copiar ao Wokwi")
    parser.add_argument("--mqtt", action="store_true", help="Incluir Wi-Fi e MQTT")
    parser.add_argument("--mqtt-config", type=Path, default=DEFAULT_CONFIG)
    parser.add_argument("--broker", help="Alterar e salvar o hostname do broker")
    args = parser.parse_args()
    config = load_config(args.mqtt_config) if args.mqtt else None
    if args.broker:
        if not config:
            parser.error("Use --mqtt ao configurar um broker.")
        config = MqttConfig(**{**asdict(config), "host": args.broker})
        args.mqtt_config.write_text(json.dumps(asdict(config), indent=2) + "\n", encoding="utf-8")
    directory = prepare(config)
    print(f"Arquivos preparados em {directory}")
    print("No Wokwi, substitua o conteúdo das abas sketch.ino e diagram.json.")
    if config:
        print("Crie também libraries.txt com o conteúdo gerado.")
        print(f"Broker: {config.host}:{config.port} | Tópicos: {config.topic}/…")
        print(f"Configuração compartilhada com o dashboard: {args.mqtt_config}")
